def calc(expr):
    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return (None, None)

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def trunc_div(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_primary():
        typ, val = peek()
        if typ == 'NUM':
            advance()
            return val
        if typ == '(':
            advance()
            v = parse_expr()
            typ2, val2 = peek()
            if typ2 != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return v
        raise ValueError(f"Unexpected token: {typ}")

    def parse_unary():
        typ, val = peek()
        if typ == '-':
            advance()
            return -parse_unary()
        if typ == '+':
            advance()
            return parse_unary()
        return parse_primary()

    def parse_term():
        v = parse_unary()
        while True:
            typ, val = peek()
            if typ == '*':
                advance()
                rhs = parse_unary()
                v = v * rhs
            elif typ == '/':
                advance()
                rhs = parse_unary()
                v = trunc_div(v, rhs)
            else:
                break
        return v

    def parse_expr():
        v = parse_term()
        while True:
            typ, val = peek()
            if typ == '+':
                advance()
                rhs = parse_term()
                v = v + rhs
            elif typ == '-':
                advance()
                rhs = parse_term()
                v = v - rhs
            else:
                break
        return v

    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

